import '@shopify/ui-extensions/preact';
import {render} from 'preact';
import {useState, useRef} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const {
    shouldShowBanner,
    visitorConsent: {
      analytics,
      marketing,
      preferences,
      saleOfData,
    },
  } = shopify.customerPrivacy.value;

  const [
    consentFormValues,
    setConsentFormValues,
  ] = useState({
    analytics,
    marketing,
    preferences,
    saleOfData,
  });

  const sheetId = 'sheet-consent';
  const modalId = 'modal-consent';
  const sheetRef = useRef();
  const modalRef = useRef();

  const getCheckboxOnChangeHandler = (key) =&gt; {
    return function (event) {
      setConsentFormValues({
        ...consentFormValues,
        [key]: event.currentTarget.checked,
      });
    };
  };

  const handleConsentChange = async (visitorConsent) =&gt; {
    try {
      const result =
        await shopify.applyTrackingConsentChange({
          ...(visitorConsent
            ? visitorConsent
            : consentFormValues),
          type: 'changeVisitorConsent',
        });

      // Check if operation was successful
      if (result.type === 'success') {
        modalRef.current?.hideOverlay();
        sheetRef.current?.hideOverlay();
      } else {
        // Handle failure case here
      }
    } catch (error) {
      // Handle error case here
    }
  };

  const consentFormMarkup = (
    &lt;s-form
      onSubmit={() =&gt; handleConsentChange()}
    &gt;
      &lt;s-stack direction="block"&gt;
        &lt;s-grid gap="base"&gt;
          &lt;s-checkbox
            id="marketing"
            label="Marketing"
            value={consentFormValues.marketing}
            onChange={getCheckboxOnChangeHandler(
              'marketing',
            )}
          /&gt;
          &lt;s-checkbox
            id="analytics"
            label="Analytics"
            value={consentFormValues.analytics}
            onChange={getCheckboxOnChangeHandler(
              'analytics',
            )}
          /&gt;
          &lt;s-checkbox
            id="preferences"
            label="Preferences"
            value={consentFormValues.preferences}
            onChange={getCheckboxOnChangeHandler(
              'preferences',
            )}
          /&gt;
          &lt;s-checkbox
            id="saleOfData"
            label="Sale of data"
            value={consentFormValues.saleOfData}
            onChange={getCheckboxOnChangeHandler(
              'saleOfData',
            )}
          /&gt;
        &lt;/s-grid&gt;
        &lt;s-button type="submit"&gt;Save&lt;/s-button&gt;
      &lt;/s-stack&gt;
    &lt;/s-form&gt;
  );

  return (
    &lt;s-sheet
      id={sheetId}
      ref={sheetRef}
      accessibilityLabel="A sheet that collects privacy consent preferences"
      defaultOpen
      // defaultOpen={shouldShowBanner}
    &gt;
      &lt;s-button
        slot="primary-action"
        variant="secondary"
        onClick={() =&gt;
          handleConsentChange({
            analytics: false,
            marketing: false,
            preferences: false,
            saleOfData: false,
          })
        }
      &gt;
        I decline
      &lt;/s-button&gt;
      &lt;s-button
        slot="primary-action"
        variant="secondary"
        onClick={() =&gt;
          handleConsentChange({
            analytics: true,
            marketing: true,
            preferences: true,
            saleOfData: true,
          })
        }
      &gt;
        I agree
      &lt;/s-button&gt;

      &lt;s-button
        slot="secondary-action"
        commandFor={modalId}
      &gt;
        Settings
      &lt;/s-button&gt;
      &lt;s-modal id={modalId} ref={modalRef}&gt;
        {consentFormMarkup}
      &lt;/s-modal&gt;

      &lt;s-paragraph&gt;
        This website uses cookies to ensure you
        get the best experience on our website.{' '}
        &lt;s-link&gt;Privacy Policy&lt;/s-link&gt;
      &lt;/s-paragraph&gt;
    &lt;/s-sheet&gt;
  );
}

