        &lt;s-text&gt;Check our latest offers&lt;/s-text&gt;
        &lt;s-link
          commandFor="modal"
          command="--show"
        &gt;
          Fill out the survey
        &lt;/s-link&gt;
      &lt;/s-stack&gt;
      &lt;s-modal
        id="modal"
        heading="Tell us about your shopping experience"
      &gt;
        &lt;s-stack gap="base"&gt;
          &lt;s-text&gt;
            We'd love to hear about your shopping
            experience
          &lt;/s-text&gt;
          &lt;s-text-area
            rows="4"
            label="How can we make your shopping experience better?"
          &gt;&lt;/s-text-area&gt;
          &lt;s-button&gt;Submit&lt;/s-button&gt;
        &lt;/s-stack&gt;
      &lt;/s-modal&gt;
    &lt;/s-announcement&gt;
  );
}

